import { supabase } from "./supabase.js";
export async function showBilling(user) {
  const { data } = await supabase.from("invoices").select("id, amount, status, created_at").eq("user_id", user.id);
  document.getElementById("panel").innerHTML = (data ?? []).map((i) => `<li>${i.amount} — ${i.status}</li>`).join("");
}
